# Türkçe metin işleme fonksiyonları
# Standart kütüphaneleri kullanır

def tr_lower(s):
    """Türkçe kurallarına göre küçük harfe çevirir."""
    # Türkçe özel karakterler
    # I -> i, İ -> ı
    result = []
    for ch in s:
        if ch == 'I':
            result.append('i')
        elif ch == 'İ':
            result.append('ı')
        elif ch.isupper():
            result.append(ch.lower())
        else:
            result.append(ch)
    return ''.join(result)


def tr_upper(s):
    """Türkçe kurallarına göre büyük harfe çevirir."""
    result = []
    for ch in s:
        if ch == 'i':
            result.append('I')
        elif ch == 'ı':
            result.append('İ')
        elif ch.islower():
            result.append(ch.upper())
        else:
            result.append(ch)
    return ''.join(result)


def tr_sorted(words):
    """
    Kelimeleri Türk alfabesine göre, büyük/küçük harf farkı gözetmeden sıralar.
    Karakter sırası: 0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz
    Özel olmayan karakterler (boşluk, noktalama vb.) listedeki tüm karakterlerden önce gelir.
    Eşit sayılan kelimeler girdideki sıralarını korur (güncellemez, stable sort).

    Girdi listesi değişmez, yeni liste döndürür.
    """
    # Türkçe karakter sırası
    tr_order = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"

    def sort_key(word):
        """Bir kelime için sıralama anahtarı döndürür."""
        key_chars = []
        for ch in word:
            # Kelimenin küçük harf versiyonunu al
            lower_ch = tr_lower(ch)

            # Karakter Türkçe karakter listesinde mi?
            if lower_ch in tr_order:
                # Türkçe karakter: sıralama pozisyonunu ekle
                key_chars.append(('turk', tr_order.index(lower_ch)))
            else:
                # Türkçe olmayan karakter: önce gelir ve Unicode'a göre
                key_chars.append(('other', ch))

        return key_chars

    # Stable sort kullan (Python'ın varsayılan sort stable)
    # Girdi listesini değiştirme için list() ile kopyala
    return sorted(list(words), key=sort_key)

